package opencode

import (
	"bufio"
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"slices"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// Compile-time interface assertions
var (
	_ agent.TranscriptAnalyzer = (*OpenCodeAgent)(nil)
	_ agent.TokenCalculator    = (*OpenCodeAgent)(nil)
)

// ParseMessages parses JSONL content (one Message per line) into a slice of Messages.
func ParseMessages(data []byte) ([]Message, error) {
	if len(data) == 0 {
		return nil, nil
	}

	var messages []Message
	reader := bufio.NewReader(bytes.NewReader(data))

	for {
		lineBytes, err := reader.ReadBytes('\n')
		if err != nil && err != io.EOF {
			return nil, fmt.Errorf("failed to read opencode transcript: %w", err)
		}

		if len(bytes.TrimSpace(lineBytes)) > 0 {
			var msg Message
			if jsonErr := json.Unmarshal(lineBytes, &msg); jsonErr == nil {
				messages = append(messages, msg)
			}
		}

		if err == io.EOF {
			break
		}
	}

	return messages, nil
}

// parseMessagesFromFile reads and parses a JSONL transcript file.
func parseMessagesFromFile(path string) ([]Message, error) {
	data, err := os.ReadFile(path) //nolint:gosec // Path from agent hook
	if err != nil {
		return nil, err //nolint:wrapcheck // Callers check os.IsNotExist on this error
	}
	return ParseMessages(data)
}

// GetTranscriptPosition returns the number of JSONL lines in the transcript.
func (a *OpenCodeAgent) GetTranscriptPosition(path string) (int, error) {
	messages, err := parseMessagesFromFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return 0, nil
		}
		return 0, err
	}
	return len(messages), nil
}

// ExtractModifiedFilesFromOffset extracts files modified by tool calls from the given message offset.
func (a *OpenCodeAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) ([]string, int, error) {
	messages, err := parseMessagesFromFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, 0, nil
		}
		return nil, 0, err
	}

	seen := make(map[string]bool)
	var files []string

	for i := startOffset; i < len(messages); i++ {
		msg := messages[i]
		if msg.Role != roleAssistant {
			continue
		}
		for _, part := range msg.Parts {
			if part.Type != "tool" || part.State == nil {
				continue
			}
			if !slices.Contains(FileModificationTools, part.Tool) {
				continue
			}
			filePath := extractFilePathFromInput(part.State.Input)
			if filePath != "" && !seen[filePath] {
				seen[filePath] = true
				files = append(files, filePath)
			}
		}
	}

	return files, len(messages), nil
}

// ExtractModifiedFiles extracts modified file paths from raw JSONL transcript bytes.
// This is the bytes-based equivalent of ExtractModifiedFilesFromOffset, used by ReadSession.
func ExtractModifiedFiles(data []byte) ([]string, error) {
	messages, err := ParseMessages(data)
	if err != nil {
		return nil, err
	}

	seen := make(map[string]bool)
	var files []string

	for _, msg := range messages {
		if msg.Role != roleAssistant {
			continue
		}
		for _, part := range msg.Parts {
			if part.Type != "tool" || part.State == nil {
				continue
			}
			if !slices.Contains(FileModificationTools, part.Tool) {
				continue
			}
			filePath := extractFilePathFromInput(part.State.Input)
			if filePath != "" && !seen[filePath] {
				seen[filePath] = true
				files = append(files, filePath)
			}
		}
	}

	return files, nil
}

// extractFilePathFromInput extracts the file path from a tool's input map.
func extractFilePathFromInput(input map[string]interface{}) string {
	for _, key := range []string{"file_path", "path", "file", "filename"} {
		if v, ok := input[key]; ok {
			if s, ok := v.(string); ok && s != "" {
				return s
			}
		}
	}
	return ""
}

// ExtractPrompts extracts user prompt strings from the transcript starting at the given offset.
func (a *OpenCodeAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
	messages, err := parseMessagesFromFile(sessionRef)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, err
	}

	var prompts []string
	for i := fromOffset; i < len(messages); i++ {
		msg := messages[i]
		if msg.Role == roleUser && msg.Content != "" {
			prompts = append(prompts, msg.Content)
		}
	}

	return prompts, nil
}

// ExtractSummary extracts the last assistant message content as a summary.
func (a *OpenCodeAgent) ExtractSummary(sessionRef string) (string, error) {
	messages, err := parseMessagesFromFile(sessionRef)
	if err != nil {
		if os.IsNotExist(err) {
			return "", nil
		}
		return "", err
	}

	for i := len(messages) - 1; i >= 0; i-- {
		msg := messages[i]
		if msg.Role == roleAssistant && msg.Content != "" {
			return msg.Content, nil
		}
	}

	return "", nil
}

// ExtractAllUserPrompts extracts all user prompts from raw JSONL transcript bytes.
// This is a package-level function used by the condensation path.
func ExtractAllUserPrompts(data []byte) ([]string, error) {
	messages, err := ParseMessages(data)
	if err != nil {
		return nil, err
	}

	var prompts []string
	for _, msg := range messages {
		if msg.Role == roleUser && msg.Content != "" {
			prompts = append(prompts, msg.Content)
		}
	}
	return prompts, nil
}

// CalculateTokenUsageFromBytes computes token usage from raw JSONL transcript bytes
// starting at the given message offset.
// This is a package-level function used by the condensation path (which has bytes, not a file path).
func CalculateTokenUsageFromBytes(data []byte, startMessageIndex int) *agent.TokenUsage {
	messages, err := ParseMessages(data)
	if err != nil || messages == nil {
		return &agent.TokenUsage{}
	}

	usage := &agent.TokenUsage{}
	for i := startMessageIndex; i < len(messages); i++ {
		msg := messages[i]
		if msg.Role != roleAssistant || msg.Tokens == nil {
			continue
		}
		usage.InputTokens += msg.Tokens.Input
		usage.OutputTokens += msg.Tokens.Output
		usage.CacheReadTokens += msg.Tokens.Cache.Read
		usage.CacheCreationTokens += msg.Tokens.Cache.Write
		usage.APICallCount++
	}

	return usage
}

// CalculateTokenUsage computes token usage from assistant messages starting at the given offset.
func (a *OpenCodeAgent) CalculateTokenUsage(sessionRef string, fromOffset int) (*agent.TokenUsage, error) {
	messages, err := parseMessagesFromFile(sessionRef)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil //nolint:nilnil // nil usage for nonexistent file is expected
		}
		return nil, fmt.Errorf("failed to parse transcript for token usage: %w", err)
	}

	usage := &agent.TokenUsage{}
	for i := fromOffset; i < len(messages); i++ {
		msg := messages[i]
		if msg.Role != roleAssistant || msg.Tokens == nil {
			continue
		}
		usage.InputTokens += msg.Tokens.Input
		usage.OutputTokens += msg.Tokens.Output
		usage.CacheReadTokens += msg.Tokens.Cache.Read
		usage.CacheCreationTokens += msg.Tokens.Cache.Write
		usage.APICallCount++
	}

	return usage, nil
}

package opencode

// sessionInfoRaw matches the JSON payload piped from the OpenCode plugin for session events.
type sessionInfoRaw struct {
	SessionID      string `json:"session_id"`
	TranscriptPath string `json:"transcript_path"`
}

// turnStartRaw matches the JSON payload for turn-start (user prompt submission).
type turnStartRaw struct {
	SessionID      string `json:"session_id"`
	TranscriptPath string `json:"transcript_path"`
	Prompt         string `json:"prompt"`
}

// --- Transcript types (JSONL format — one Message per line) ---

// Message role constants.
const (
	roleAssistant = "assistant"
	roleUser      = "user"
)

// Message represents a single message (one line) in the JSONL transcript.
type Message struct {
	ID      string  `json:"id"`
	Role    string  `json:"role"` // "user" or "assistant"
	Content string  `json:"content"`
	Time    Time    `json:"time"`
	Tokens  *Tokens `json:"tokens,omitempty"`
	Cost    float64 `json:"cost,omitempty"`
	Parts   []Part  `json:"parts,omitempty"`
}

// Time holds message timestamps.
type Time struct {
	Created   int64 `json:"created"`
	Completed int64 `json:"completed,omitempty"`
}

// Tokens holds token usage from assistant messages.
type Tokens struct {
	Input     int   `json:"input"`
	Output    int   `json:"output"`
	Reasoning int   `json:"reasoning"`
	Cache     Cache `json:"cache"`
}

// Cache holds cache-related token counts.
type Cache struct {
	Read  int `json:"read"`
	Write int `json:"write"`
}

// Part represents a message part (text, tool, etc.).
type Part struct {
	Type   string     `json:"type"` // "text", "tool", etc.
	Text   string     `json:"text,omitempty"`
	Tool   string     `json:"tool,omitempty"`
	CallID string     `json:"callID,omitempty"`
	State  *ToolState `json:"state,omitempty"`
}

// ToolState represents tool execution state.
type ToolState struct {
	Status string                 `json:"status"` // "pending", "running", "completed", "error"
	Input  map[string]interface{} `json:"input,omitempty"`
	Output string                 `json:"output,omitempty"`
}

// FileModificationTools are tools in OpenCode that modify files on disk.
// These match the actual tool names from OpenCode's source:
//   - edit:  internal/llm/tools/edit.go  (EditToolName)
//   - write: internal/llm/tools/write.go (WriteToolName)
//   - patch: internal/llm/tools/patch.go (PatchToolName)
var FileModificationTools = []string{
	"edit",
	"write",
	"patch",
}

// Entire CLI plugin for OpenCode
// Auto-generated by `entire enable --agent opencode`
// Do not edit manually — changes will be overwritten on next install.
// Requires Bun runtime (used by OpenCode's plugin system for loading ESM plugins).
import type { Plugin } from "@opencode-ai/plugin"
import { tmpdir } from "node:os"

export const EntirePlugin: Plugin = async ({ client, directory, $ }) => {
  const ENTIRE_CMD = "__ENTIRE_CMD__"
  // Store transcripts in a temp directory — these are ephemeral handoff files
  // between the plugin and the Go hook handler. Once checkpointed, the data
  // lives on git refs and the file is disposable.
  const sanitized = directory.replace(/[^a-zA-Z0-9]/g, "-")
  const transcriptDir = `${tmpdir()}/entire-opencode/${sanitized}`
  const seenUserMessages = new Set<string>()

  // In-memory stores — used to write transcripts without relying on the SDK API,
  // which may be unavailable during shutdown.
  // messageStore: keyed by message ID, stores message metadata (role, time, tokens, etc.)
  const messageStore = new Map<string, any>()
  // partStore: keyed by message ID, stores accumulated parts from message.part.updated events
  const partStore = new Map<string, any[]>()
  let currentSessionID: string | null = null
  // Full session info from session.created — needed for OpenCode export format on resume/rewind
  let currentSessionInfo: any = null

  // Ensure transcript directory exists
  await $`mkdir -p ${transcriptDir}`.quiet().nothrow()

  /**
   * Pipe JSON payload to an entire hooks command.
   * Errors are logged but never thrown — plugin failures must not crash OpenCode.
   */
  async function callHook(hookName: string, payload: Record<string, unknown>) {
    try {
      const json = JSON.stringify(payload)
      await $`echo ${json} | ${ENTIRE_CMD} hooks opencode ${hookName}`.quiet().nothrow()
    } catch {
      // Silently ignore — plugin failures must not crash OpenCode
    }
  }

  /** Extract text content from a list of parts. */
  function textFromParts(parts: any[]): string {
    return parts
      .filter((p: any) => p.type === "text")
      .map((p: any) => p.text ?? "")
      .join("\n")
  }

  /** Format a message object from its accumulated parts. */
  function formatMessageFromStore(msg: any) {
    const parts = partStore.get(msg.id) ?? []
    return {
      id: msg.id,
      role: msg.role,
      content: textFromParts(parts),
      time: msg.time,
      ...(msg.role === "assistant" ? {
        tokens: msg.tokens,
        cost: msg.cost,
        parts: parts.map((p: any) => ({
          type: p.type,
          ...(p.type === "text" ? { text: p.text } : {}),
          ...(p.type === "tool" ? { tool: p.tool, callID: p.callID, state: p.state } : {}),
        })),
      } : {}),
    }
  }

  /** Format a message from an API response (which includes parts inline). */
  function formatMessageFromAPI(info: any, parts: any[]) {
    return {
      id: info.id,
      role: info.role,
      content: textFromParts(parts),
      time: info.time,
      ...(info.role === "assistant" ? {
        tokens: info.tokens,
        cost: info.cost,
        parts: parts.map((p: any) => ({
          type: p.type,
          ...(p.type === "text" ? { text: p.text } : {}),
          ...(p.type === "tool" ? { tool: p.tool, callID: p.callID, state: p.state } : {}),
        })),
      } : {}),
    }
  }

  /**
   * Write transcript as JSONL (one message per line) from in-memory stores.
   * This does NOT call the SDK API, so it works even during shutdown.
   */
  async function writeTranscriptFromMemory(sessionID: string): Promise<string> {
    const transcriptPath = `${transcriptDir}/${sessionID}.jsonl`
    try {
      const messages = Array.from(messageStore.values())
        .sort((a, b) => (a.time?.created ?? 0) - (b.time?.created ?? 0))

      const lines = messages.map(msg => JSON.stringify(formatMessageFromStore(msg)))
      await Bun.write(transcriptPath, lines.join("\n") + "\n")
    } catch {
      // Silently ignore write failures
    }
    return transcriptPath
  }

  /**
   * Try to fetch messages via the SDK API (returns messages with parts inline)
   * and write transcript as JSONL. Falls back to in-memory stores if the API is unavailable.
   */
  async function writeTranscriptWithFallback(sessionID: string): Promise<string> {
    const transcriptPath = `${transcriptDir}/${sessionID}.jsonl`
    try {
      const response = await client.session.message.list({ path: { id: sessionID } })
      // API returns Array<{ info: Message, parts: Array<Part> }>
      const items = response.data ?? []

      const lines = items.map((item: any) =>
        JSON.stringify(formatMessageFromAPI(item.info, item.parts ?? []))
      )
      await Bun.write(transcriptPath, lines.join("\n") + "\n")
      return transcriptPath
    } catch {
      // API unavailable (likely shutting down) — fall back to in-memory stores
      return writeTranscriptFromMemory(sessionID)
    }
  }

  /**
   * Write session in OpenCode's native export format (JSON).
   * This file is used by `opencode import` during resume/rewind to restore
   * the session into OpenCode's SQLite database with the original session ID.
   */
  async function writeExportJSON(sessionID: string): Promise<string> {
    const exportPath = `${transcriptDir}/${sessionID}.export.json`
    try {
      const messages = Array.from(messageStore.values())
        .sort((a, b) => (a.time?.created ?? 0) - (b.time?.created ?? 0))

      const exportData = {
        info: currentSessionInfo ?? { id: sessionID },
        messages: messages.map(msg => ({
          info: msg,
          parts: (partStore.get(msg.id) ?? []),
        })),
      }
      await Bun.write(exportPath, JSON.stringify(exportData))
    } catch {
      // Silently ignore — plugin failures must not crash OpenCode
    }
    return exportPath
  }

  return {
    event: async ({ event }) => {
      switch (event.type) {
        case "session.created": {
          const session = (event as any).properties?.info
          if (!session?.id) break
          currentSessionID = session.id
          currentSessionInfo = session
          await callHook("session-start", {
            session_id: session.id,
            transcript_path: `${transcriptDir}/${session.id}.jsonl`,
          })
          break
        }

        case "message.updated": {
          const msg = (event as any).properties?.info
          if (!msg) break
          // Store message metadata (role, time, tokens, etc.)
          // Content is NOT on the message — it arrives via message.part.updated events.
          messageStore.set(msg.id, msg)
          break
        }

        case "message.part.updated": {
          const part = (event as any).properties?.part
          if (!part?.messageID) break

          // Accumulate parts per message
          const existing = partStore.get(part.messageID) ?? []
          // Replace existing part with same id, or append new one
          const idx = existing.findIndex((p: any) => p.id === part.id)
          if (idx >= 0) {
            existing[idx] = part
          } else {
            existing.push(part)
          }
          partStore.set(part.messageID, existing)

          // Fire turn-start on the first text part of a new user message
          const msg = messageStore.get(part.messageID)
          if (msg?.role === "user" && part.type === "text" && !seenUserMessages.has(msg.id)) {
            seenUserMessages.add(msg.id)
            const sessionID = msg.sessionID ?? currentSessionID
            if (sessionID) {
              await callHook("turn-start", {
                session_id: sessionID,
                transcript_path: `${transcriptDir}/${sessionID}.jsonl`,
                prompt: part.text ?? "",
              })
            }
          }
          break
        }

        case "session.idle": {
          const sessionID = (event as any).properties?.sessionID
          if (!sessionID) break
          const transcriptPath = await writeTranscriptWithFallback(sessionID)
          await writeExportJSON(sessionID)
          await callHook("turn-end", {
            session_id: sessionID,
            transcript_path: transcriptPath,
          })
          break
        }

        case "session.compacted": {
          const sessionID = (event as any).properties?.sessionID
          if (!sessionID) break
          await callHook("compaction", {
            session_id: sessionID,
            transcript_path: `${transcriptDir}/${sessionID}.jsonl`,
          })
          break
        }

        case "session.deleted": {
          const session = (event as any).properties?.info
          if (!session?.id) break
          // Write final transcript + export JSON before signaling session end
          if (messageStore.size > 0) {
            await writeTranscriptFromMemory(session.id)
            await writeExportJSON(session.id)
          }
          seenUserMessages.clear()
          messageStore.clear()
          partStore.clear()
          currentSessionID = null
          currentSessionInfo = null
          await callHook("session-end", {
            session_id: session.id,
            transcript_path: `${transcriptDir}/${session.id}.jsonl`,
          })
          break
        }
      }
    },
  }
}

