	env.T.Helper()

	// Session state is stored in .git/entire-sessions/<session-id>.json
	stateFile := filepath.Join(env.RepoDir, ".git", "entire-sessions", sessionID+".json")

	if err := os.Remove(stateFile); err != nil && !os.IsNotExist(err) {
