					Tokens: &Tokens{Input: 150, Output: 80, Reasoning: 10, Cache: Cache{Read: 5, Write: 15}},
					Cost:   0.003,
				},
				Parts: []Part{
					{Type: "text", Text: "I'll fix the bug."},
