func (env *TestEnv) SimulateSessionEnd(sessionID string) error {
	env.T.Helper()
	runner := NewHookRunner(env.RepoDir, env.ClaudeProjectDir, env.T)
	return runner.SimulateSessionEnd(sessionID)
