// Files outside .entire/tmp/ are left alone (they belong to the agent).
func CleanupCachedTranscript(transcriptPath string) error {
	if transcriptPath == "" {
		return nil
	}

	// Get the tmp directory path
	tmpDirAbs, err := paths.AbsPath(paths.EntireTmpDir)
	if err != nil {
		tmpDirAbs = paths.EntireTmpDir
	}

	// Check if the transcript is in .entire/tmp/
	absPath, err := filepath.Abs(transcriptPath)
	if err != nil {
		return nil // Can't determine path, skip cleanup
	}

	// Only clean up files in .entire/tmp/
	if !strings.HasPrefix(absPath, tmpDirAbs) {
		return nil
	}

	if fileExists(transcriptPath) {
		return os.Remove(transcriptPath) //nolint:wrapcheck
	}
	return nil
}

